    # 30x30 repetition is centrosymmetric; restore masked cells from opposite
    # positions while retaining all visible cells.
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                out[r][c] = grid[n - 1 - r][m - 1 - c]
    return out

